-- Observational Fleet history only. No execution/financial proof publication.
CREATE FUNCTION fleet_history_json_text(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result text; BEGIN
 CASE jsonb_typeof(v)
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(fleet_history_json_text(to_jsonb(key))||':'||fleet_history_json_text(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(fleet_history_json_text(value),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ordinal);
 ELSE result:=v::text;
 END CASE;
 RETURN replace(replace(replace(replace(replace(result,'<','\u003c'),'>','\u003e'),'&','\u0026'),chr(8232),'\u2028'),chr(8233),'\u2029');
END $$;
CREATE FUNCTION fleet_history_json_hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$ SELECT encode(sha256(convert_to(fleet_history_json_text(v),'UTF8')),'hex') $$;
CREATE FUNCTION fleet_history_source_config(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT fleet_history_json_hash(jsonb_build_object('kind',v->'kind','payer_account_id',v->'payer_account_id','usage_account_ids',coalesce((SELECT jsonb_agg(value ORDER BY value::text COLLATE "C") FROM jsonb_array_elements(v->'usage_account_ids')),'[]'::jsonb),'region',v->'region','export_arn',v->'export_arn','bucket',v->'bucket','bucket_owner',v->'bucket_owner','prefix',v->'prefix','read_role_binding_id',v->'read_role_binding_id'))
$$;
CREATE FUNCTION fleet_history_lock(p_tenant text,p_registration text) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN
 IF p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) OR coalesce(p_registration,'')='' THEN RAISE EXCEPTION 'fleet history tenant or registration mismatch'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant||':fleet-history:'||p_registration,0));
END $$;
CREATE FUNCTION fleet_history_source_lock(p_tenant text,p_source text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN
 IF p_tenant IS NULL OR p_tenant='' OR p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) OR coalesce(p_source,'')='' THEN RAISE EXCEPTION 'fleet history source tenant mismatch'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(p_tenant||':trusted-source:'||p_source,0)) THEN RAISE EXCEPTION 'fleet history source synchronization busy'; END IF;
 PERFORM 1 FROM public.source_registrations WHERE tenant_id=p_tenant AND id=p_source FOR SHARE;
 RETURN FOUND;
END $$;
REVOKE ALL ON FUNCTION fleet_history_source_lock(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_history_source_lock(text,text) TO finops_api,finops_ingester;

CREATE TABLE fleet_history_registrations (
 tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),workload_id text NOT NULL,source_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id,version),FOREIGN KEY(tenant_id,source_id) REFERENCES source_registrations(tenant_id,id),CHECK(octet_length(raw_document)<=32768)
);
CREATE TABLE fleet_demand_definitions (
 tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),registration_id text NOT NULL,registration_version bigint NOT NULL,workload_id text NOT NULL,source_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id,version),FOREIGN KEY(tenant_id,registration_id,registration_version) REFERENCES fleet_history_registrations(tenant_id,id,version),FOREIGN KEY(tenant_id,source_id) REFERENCES activity_sources(tenant_id,id),CHECK(octet_length(raw_document)<=32768)
);
CREATE TABLE fleet_history_observations (
 tenant_id text NOT NULL,id text NOT NULL,registration_id text NOT NULL,registration_version bigint NOT NULL,native_receipt_id text NOT NULL,observed_at timestamptz NOT NULL,corrects_id text,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,registration_id,registration_version,native_receipt_id),FOREIGN KEY(tenant_id,registration_id,registration_version) REFERENCES fleet_history_registrations(tenant_id,id,version),FOREIGN KEY(tenant_id,native_receipt_id) REFERENCES source_receipts(tenant_id,id),FOREIGN KEY(tenant_id,corrects_id) REFERENCES fleet_history_observations(tenant_id,id),CHECK(octet_length(raw_document)<=1048576)
);
CREATE INDEX fleet_history_observations_window ON fleet_history_observations(tenant_id,registration_id,registration_version,observed_at,id);
CREATE TABLE fleet_history_scopes (
 tenant_id text NOT NULL,id text NOT NULL,registration_id text NOT NULL,registration_version bigint NOT NULL,definition_id text NOT NULL,definition_version bigint NOT NULL,
 input_hash text NOT NULL CHECK(input_hash~'^[a-f0-9]{64}$'),analysis_hash text NOT NULL CHECK(analysis_hash~'^[a-f0-9]{64}$'),reference_root text NOT NULL CHECK(reference_root~'^[a-f0-9]{64}$'),reference_count integer NOT NULL CHECK(reference_count BETWEEN 2 AND 50000),
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,analysis_hash),FOREIGN KEY(tenant_id,registration_id,registration_version) REFERENCES fleet_history_registrations(tenant_id,id,version),FOREIGN KEY(tenant_id,definition_id,definition_version) REFERENCES fleet_demand_definitions(tenant_id,id,version),CHECK(octet_length(raw_document)<=65536)
);
CREATE TABLE fleet_history_scope_references (
 tenant_id text NOT NULL,scope_id text NOT NULL,ordinal integer NOT NULL CHECK(ordinal>0),kind text NOT NULL CHECK(kind IN('REGISTRATION','DEFINITION','OBSERVATION','DEMAND_RECEIPT','SOURCE_STATE')),reference_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,scope_id,ordinal),UNIQUE(tenant_id,scope_id,kind,reference_id),FOREIGN KEY(tenant_id,scope_id) REFERENCES fleet_history_scopes(tenant_id,id),CHECK(octet_length(raw_document)<=32768)
);
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fleet_history_registrations','fleet_demand_definitions','fleet_history_observations','fleet_history_scopes','fleet_history_scope_references'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK(tenant_id=current_setting(''app.tenant_id'',true))',tab);
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION deny_evidence_mutation()',tab||'_immutable',tab);
 END LOOP;END $$;
GRANT SELECT ON fleet_history_registrations,fleet_demand_definitions,fleet_history_observations,fleet_history_scopes,fleet_history_scope_references TO finops_api,finops_ingester;
GRANT INSERT ON fleet_history_registrations,fleet_demand_definitions,fleet_history_scopes,fleet_history_scope_references TO finops_api;
GRANT INSERT ON fleet_history_observations TO finops_ingester;

-- Check only references already issued by the native ingester, never uploaded
-- native-looking dictionaries. Archive readback itself remains collector duty.
CREATE FUNCTION fleet_history_native_reference(p_tenant text,ref jsonb,binding jsonb,p_kind text,p_target text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE receipt source_receipts%ROWTYPE;revision source_revisions%ROWTYPE;registration source_registrations%ROWTYPE;native jsonb; BEGIN
 IF NOT ref ?& ARRAY['kind','binding','source_id','source_system','revision_id','source_registration_version','config_hash','receipt_id','target','raw_sha256','canonical_hash','captured_at','storage_kind','archive'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(ref) k WHERE k<>ALL(ARRAY['kind','binding','source_id','source_system','revision_id','source_registration_version','config_hash','receipt_id','target','raw_sha256','canonical_hash','captured_at','storage_kind','archive'])) OR coalesce(ref->>'raw_sha256','') !~ '^[a-f0-9]{64}$' OR coalesce(ref->>'canonical_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(ref->>'config_hash','') !~ '^[a-f0-9]{64}$' OR coalesce((ref->>'source_registration_version')::bigint,0)<1 OR coalesce(ref->'archive'->>'bucket','')='' OR position('..' IN coalesce(ref->'archive'->>'key',''))>0 OR position(chr(92) IN coalesce(ref->'archive'->>'key',''))>0 THEN RAISE EXCEPTION 'fleet history native reference shape differs'; END IF;
 IF p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) OR ref->'binding' IS DISTINCT FROM binding OR ref->>'source_system' IS DISTINCT FROM 'AWS_SOURCE_CONNECTION' OR ref->>'storage_kind' IS DISTINCT FROM 'VERSIONED_OBJECT' OR ref->>'kind' IS DISTINCT FROM p_kind OR ref->>'target' IS DISTINCT FROM p_target THEN RAISE EXCEPTION 'fleet history native reference scope mismatch'; END IF;
 IF NOT fleet_history_source_lock(p_tenant,ref->>'source_id') THEN RAISE EXCEPTION 'fleet history source missing'; END IF;
 SELECT * INTO registration FROM source_registrations WHERE tenant_id=p_tenant AND id=ref->>'source_id';
 SELECT * INTO receipt FROM source_receipts WHERE tenant_id=p_tenant AND id=ref->>'receipt_id';
 SELECT * INTO revision FROM source_revisions WHERE tenant_id=p_tenant AND id=ref->>'revision_id';
 IF revision.document->>'kind' IS DISTINCT FROM p_kind OR registration.document->>'region' IS DISTINCT FROM binding->>'region' OR NOT coalesce(registration.document->>'payer_account_id'=binding->>'account_id' OR registration.document->'usage_account_ids' ? (binding->>'account_id'),false) THEN RAISE EXCEPTION 'fleet history issued source account or kind differs'; END IF;
 IF receipt.id IS NULL OR revision.id IS NULL OR receipt.writer_role<>'finops_ingester' OR revision.writer_role<>'finops_ingester' OR receipt.kind IS DISTINCT FROM p_kind OR receipt.source_id IS DISTINCT FROM registration.id OR receipt.revision_id IS DISTINCT FROM revision.id OR revision.source_id IS DISTINCT FROM registration.id OR receipt.document->>'revision_id' IS DISTINCT FROM revision.id OR receipt.document->>'source_id' IS DISTINCT FROM registration.id OR NOT coalesce((registration.document->>'enabled')::boolean,false) OR coalesce((registration.document->>'revoked')::boolean,false) THEN RAISE EXCEPTION 'fleet history native receipt unavailable'; END IF;
 IF ref->>'config_hash' IS DISTINCT FROM fleet_history_source_config(registration.document) OR ref->>'config_hash' IS DISTINCT FROM receipt.document->>'config_hash' OR ref->>'config_hash' IS DISTINCT FROM revision.document->>'config_hash' OR (ref->>'source_registration_version')::bigint IS DISTINCT FROM (receipt.document->>'registration_version')::bigint OR (ref->>'source_registration_version')::bigint>registration.version OR receipt.document->>'read_role_binding_id' IS DISTINCT FROM registration.document->>'read_role_binding_id' THEN RAISE EXCEPTION 'fleet history source configuration differs'; END IF;
 IF receipt.document->'binding'->>'tenant_id' IS DISTINCT FROM p_tenant OR receipt.document->'binding'->>'workload_id' IS DISTINCT FROM binding->>'workload_id' OR receipt.document->'binding'->>'provider' IS DISTINCT FROM 'AWS' OR receipt.document->'binding'->>'account_id' IS DISTINCT FROM binding->>'account_id' OR receipt.document->'binding'->>'region' IS DISTINCT FROM 'eu-west-1' THEN RAISE EXCEPTION 'fleet history receipt provider binding differs'; END IF;
 IF ref->>'canonical_hash' IS DISTINCT FROM fleet_history_json_hash(receipt.document) OR ref->>'raw_sha256' IS DISTINCT FROM receipt.document->'raw_object'->>'body_sha256' OR ref->>'raw_sha256' !~ '^[a-f0-9]{64}$' OR (ref->>'captured_at')::timestamptz IS DISTINCT FROM (receipt.document->>'collected_at')::timestamptz OR receipt.document->'raw_object'->>'bucket' IS DISTINCT FROM revision.document->'raw_object'->>'bucket' OR receipt.document->'raw_object'->>'key' IS DISTINCT FROM revision.document->'raw_object'->>'key' OR receipt.document->'raw_object'->>'body_sha256' IS DISTINCT FROM revision.document->'raw_object'->>'body_sha256' OR coalesce(revision.document->'raw_object'->>'version_id','') IN('','null') OR ref->'archive' IS DISTINCT FROM jsonb_build_object('bucket',receipt.document->'raw_object'->'bucket','key',receipt.document->'raw_object'->'key','version_id',receipt.document->'raw_object'->'version_id','sha256',receipt.document->'raw_object'->'body_sha256') OR coalesce(ref->'archive'->>'version_id','') IN('','null') OR left(ref->'archive'->>'key',length('tenant/'||p_tenant||'/')) IS DISTINCT FROM 'tenant/'||p_tenant||'/' THEN RAISE EXCEPTION 'fleet history pinned native bytes differ'; END IF;
 IF p_kind='AWS_EC2_HARDWARE' AND (receipt.document->'native'->'instance'->>'id' IS DISTINCT FROM p_target OR receipt.document->'native'->>'account_id' IS DISTINCT FROM binding->>'account_id' OR receipt.document->'native'->>'region' IS DISTINCT FROM binding->>'region') THEN RAISE EXCEPTION 'fleet history hardware instance differs'; END IF;
 RETURN receipt.document||jsonb_build_object('_receipt_created_at',receipt.created_at);
END $$;

CREATE FUNCTION guard_fleet_history() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE r jsonb;definition jsonb;source jsonb;source_version bigint;v bigint;native jsonb;native_group jsonb;member jsonb;native_member jsonb;hardware jsonb;old jsonb;scope fleet_history_scopes%ROWTYPE;expected_hash text;expected_status text;source_status jsonb; BEGIN
 IF NEW.tenant_id IS DISTINCT FROM current_setting('app.tenant_id',true) THEN RAISE EXCEPTION 'fleet history tenant mismatch'; END IF;
 IF TG_TABLE_NAME='fleet_history_observations' THEN
  IF NOT pg_has_role(current_user,'finops_ingester','MEMBER') THEN RAISE EXCEPTION 'fleet history observations require ingester'; END IF;NEW.writer_role:='finops_ingester';
 ELSE IF NOT pg_has_role(current_user,'finops_api','MEMBER') THEN RAISE EXCEPTION 'fleet history declarations and scope require API'; END IF;NEW.writer_role:='finops_api'; END IF;
 NEW.created_at:=clock_timestamp();
 IF encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document OR jsonb_typeof(NEW.document) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'fleet history exact document hash differs'; END IF;
 IF TG_TABLE_NAME='fleet_history_registrations' THEN
  IF NOT NEW.document ?& ARRAY['schema_version','id','version','fleet_id','binding','asg_arn','source_id','source_system','source_registration_version','source_config_hash','cadence_seconds','max_gap_seconds'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','version','fleet_id','binding','asg_arn','source_id','source_system','source_registration_version','source_config_hash','cadence_seconds','max_gap_seconds'])) OR coalesce(NEW.document->'binding'->>'account_id','') !~ '^[0-9]{12}$' OR coalesce(NEW.document->>'fleet_id','')='' OR coalesce((NEW.document->>'cadence_seconds')::integer,0) NOT BETWEEN 1 AND 600 OR coalesce((NEW.document->>'max_gap_seconds')::integer,0) NOT BETWEEN (NEW.document->>'cadence_seconds')::integer AND 600 THEN RAISE EXCEPTION 'fleet history registration shape differs'; END IF;
  PERFORM fleet_history_lock(NEW.tenant_id,NEW.id);
  SELECT coalesce(max(version),0)+1 INTO v FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
  SELECT document INTO r FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.id ORDER BY version DESC LIMIT 1;
  IF r IS NOT NULL AND (r->'binding' IS DISTINCT FROM NEW.document->'binding' OR r->>'fleet_id' IS DISTINCT FROM NEW.document->>'fleet_id' OR r->>'asg_arn' IS DISTINCT FROM NEW.document->>'asg_arn') THEN RAISE EXCEPTION 'fleet history registration identity is immutable'; END IF;
  IF NEW.version<>v OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR (NEW.document->>'version')::bigint IS DISTINCT FROM NEW.version OR NEW.document->'binding'->>'tenant_id' IS DISTINCT FROM NEW.tenant_id OR NEW.document->'binding'->>'workload_id' IS DISTINCT FROM NEW.workload_id OR NEW.document->'binding'->>'provider' IS DISTINCT FROM 'AWS' OR NEW.document->'binding'->>'region' IS DISTINCT FROM 'eu-west-1' OR NEW.document->>'source_system' IS DISTINCT FROM 'AWS_SOURCE_CONNECTION' OR NEW.document->>'source_id' IS DISTINCT FROM NEW.source_id OR NEW.document->>'asg_arn' !~ ('^arn:aws:autoscaling:eu-west-1:'||(NEW.document->'binding'->>'account_id')||':autoScalingGroup:[a-f0-9-]{36}:autoScalingGroupName/[^*?]+$') OR NOT EXISTS(SELECT 1 FROM entities WHERE tenant_id=NEW.tenant_id AND kind='workloads' AND id=NEW.workload_id) THEN RAISE EXCEPTION 'fleet history registration binding or CAS differs'; END IF;
  IF NOT fleet_history_source_lock(NEW.tenant_id,NEW.source_id) THEN RAISE EXCEPTION 'fleet history registration source missing'; END IF;
  SELECT document,version INTO source,source_version FROM source_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.source_id;
  IF NEW.document->>'source_config_hash' IS DISTINCT FROM fleet_history_source_config(source) OR (NEW.document->>'source_registration_version')::bigint IS DISTINCT FROM source_version OR source->>'enabled' IS DISTINCT FROM 'true' OR coalesce((source->>'revoked')::boolean,false) OR source->>'region' IS DISTINCT FROM 'eu-west-1' OR NOT (source->>'payer_account_id'=NEW.document->'binding'->>'account_id' OR source->'usage_account_ids' ? (NEW.document->'binding'->>'account_id')) THEN RAISE EXCEPTION 'fleet history registration source scope differs'; END IF;
 ELSIF TG_TABLE_NAME='fleet_demand_definitions' THEN
  IF NOT NEW.document ?& ARRAY['schema_version','id','version','binding','aggregation','meaning','business_operation','unit','metric','metric_definition_id','metric_definition_version','value_field','origin','semantic_contract_id','semantic_contract_hash','source_id','source_system','source_config_hash','temporality','cadence_seconds','max_gap_seconds'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','version','binding','aggregation','meaning','business_operation','unit','metric','metric_definition_id','metric_definition_version','value_field','origin','semantic_contract_id','semantic_contract_hash','source_id','source_system','source_config_hash','temporality','cadence_seconds','max_gap_seconds'])) OR coalesce(NEW.document->>'business_operation','')='' OR coalesce(NEW.document->>'semantic_contract_hash','') !~ '^[a-f0-9]{64}$' OR coalesce((NEW.document->>'cadence_seconds')::integer,0) NOT BETWEEN 1 AND 600 OR coalesce((NEW.document->>'max_gap_seconds')::integer,0) NOT BETWEEN (NEW.document->>'cadence_seconds')::integer AND 600 THEN RAISE EXCEPTION 'fleet completed-work definition shape differs'; END IF;
  PERFORM fleet_history_lock(NEW.tenant_id,NEW.registration_id);
  PERFORM fleet_history_lock(NEW.tenant_id,'definition:'||NEW.id);
  IF EXISTS(SELECT 1 FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=NEW.id AND registration_id<>NEW.registration_id) THEN RAISE EXCEPTION 'fleet demand definition registration is immutable'; END IF;
  SELECT document INTO r FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id AND version=NEW.registration_version;
  SELECT coalesce(max(version),0)+1 INTO v FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=NEW.id;
  SELECT document INTO source FROM activity_sources WHERE tenant_id=NEW.tenant_id AND id=NEW.source_id;
  IF r IS NULL OR source IS NULL OR NEW.registration_version IS DISTINCT FROM (SELECT max(version) FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id) OR NEW.version<>v OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR (NEW.document->>'version')::bigint IS DISTINCT FROM NEW.version OR NEW.document->'binding' IS DISTINCT FROM r->'binding' OR NEW.workload_id IS DISTINCT FROM r->'binding'->>'workload_id' OR NEW.document->>'source_id' IS DISTINCT FROM NEW.source_id OR NEW.document->>'source_system' IS DISTINCT FROM 'ACTIVITY_SOURCE' OR NEW.document ? 'source_registration_version' OR NEW.document->>'source_config_hash' IS DISTINCT FROM fleet_history_json_hash(source) OR NEW.document->>'metric' IS DISTINCT FROM 'activity.Completed' OR NEW.document->>'value_field' IS DISTINCT FROM 'COMPLETED' OR NEW.document->>'temporality' IS DISTINCT FROM 'DELTA' OR NEW.document->>'meaning' IS DISTINCT FROM 'COMPLETED_WORK' OR NEW.document->>'origin' IS DISTINCT FROM 'INDEPENDENT_EXTERNAL_SYSTEM' OR NEW.document->>'aggregation' IS DISTINCT FROM 'SINGLE_EXTERNAL_TOTAL' OR coalesce(NEW.document->>'semantic_contract_id','')='' OR NEW.document->>'semantic_contract_hash' !~ '^[a-f0-9]{64}$' OR source->>'enabled' IS DISTINCT FROM 'true' OR source->>'workload_id' IS DISTINCT FROM NEW.workload_id OR source->>'account_id' IS DISTINCT FROM r->'binding'->>'account_id' OR source->>'region' IS DISTINCT FROM r->'binding'->>'region' OR source->'metric_definition'->>'id' IS DISTINCT FROM NEW.document->>'metric_definition_id' OR source->'metric_definition'->>'version' IS DISTINCT FROM NEW.document->>'metric_definition_version' OR source->'metric_definition'->>'unit' IS DISTINCT FROM NEW.document->>'unit' THEN RAISE EXCEPTION 'fleet completed-work definition scope or CAS differs'; END IF;
 ELSIF TG_TABLE_NAME='fleet_history_observations' THEN
  IF NOT NEW.document ?& ARRAY['schema_version','id','registration_id','registration_version','registration_hash','asg_arn','observed_at','received_at','source','members'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','registration_id','registration_version','registration_hash','asg_arn','observed_at','received_at','source','members','corrects_id'])) OR NEW.document->>'schema_version' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'fleet history observation shape differs'; END IF;
  PERFORM fleet_history_lock(NEW.tenant_id,NEW.registration_id);
  SELECT document INTO r FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id AND version=NEW.registration_version;
  IF r IS NULL OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->>'registration_id' IS DISTINCT FROM NEW.registration_id OR (NEW.document->>'registration_version')::bigint IS DISTINCT FROM NEW.registration_version OR NEW.document->>'registration_hash' IS DISTINCT FROM (SELECT content_hash FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id AND version=NEW.registration_version) OR NEW.document->>'asg_arn' IS DISTINCT FROM r->>'asg_arn' OR NEW.document->'source'->>'receipt_id' IS DISTINCT FROM NEW.native_receipt_id OR (NEW.document->>'observed_at')::timestamptz IS DISTINCT FROM NEW.observed_at OR NEW.observed_at>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION 'fleet history observation registration differs'; END IF;
  native:=fleet_history_native_reference(NEW.tenant_id,NEW.document->'source',r->'binding','AWS_FLEET_MEMBERSHIP',r->>'asg_arn');
  IF NEW.document->'source'->>'source_id' IS DISTINCT FROM r->>'source_id' OR NEW.document->'source'->>'config_hash' IS DISTINCT FROM r->>'source_config_hash' OR coalesce((NEW.document->'source'->>'source_registration_version')::bigint,0)<(r->>'source_registration_version')::bigint THEN RAISE EXCEPTION 'fleet history observation source registration differs'; END IF;
  IF (NEW.document->>'received_at')::timestamptz IS DISTINCT FROM (native->>'_receipt_created_at')::timestamptz OR NEW.observed_at IS DISTINCT FROM (native->>'collected_at')::timestamptz OR (SELECT count(*) FROM jsonb_array_elements(native->'groups') g WHERE g->>'arn'=r->>'asg_arn')<>1 THEN RAISE EXCEPTION 'fleet history native observation time or group differs'; END IF;
  SELECT g INTO native_group FROM jsonb_array_elements(native->'groups') g WHERE g->>'arn'=r->>'asg_arn';
  IF jsonb_typeof(NEW.document->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'members')<>jsonb_array_length(coalesce(native_group->'members','[]'::jsonb)) OR jsonb_array_length(NEW.document->'members')>256 OR (SELECT count(DISTINCT m->>'instance_id') FROM jsonb_array_elements(NEW.document->'members') m)<>jsonb_array_length(NEW.document->'members') THEN RAISE EXCEPTION 'fleet history native members differ'; END IF;
  FOR member IN SELECT * FROM jsonb_array_elements(NEW.document->'members') LOOP
   IF NOT member ?& ARRAY['instance_id','launch_time','launch_template_id','launch_template_version','hardware'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(member) k WHERE k<>ALL(ARRAY['instance_id','launch_time','launch_template_id','launch_template_version','resource_id','hardware'])) OR coalesce(member->>'instance_id','') !~ '^i-([a-f0-9]{8}|[a-f0-9]{17})$' OR coalesce(member->>'launch_template_id','') !~ '^lt-([a-f0-9]{8}|[a-f0-9]{17})$' OR coalesce((member->>'launch_template_version')::numeric,0)<1 OR (member->>'launch_time')::timestamptz>NEW.observed_at THEN RAISE EXCEPTION 'fleet history member shape differs'; END IF;
   SELECT m INTO native_member FROM jsonb_array_elements(native_group->'members') m WHERE m->>'instance_id'=member->>'instance_id';
   IF native_member IS NULL OR native_member->'launch_template'->>'id' IS DISTINCT FROM member->>'launch_template_id' OR (native_member->'launch_template'->>'version')::numeric IS DISTINCT FROM (member->>'launch_template_version')::numeric THEN RAISE EXCEPTION 'fleet history native member template differs'; END IF;
   IF coalesce(member->>'resource_id','')<>'' AND NOT EXISTS(SELECT 1 FROM entities WHERE tenant_id=NEW.tenant_id AND kind='resources' AND id=member->>'resource_id' AND document->>'workload_id'=r->'binding'->>'workload_id' AND document->>'provider'='AWS' AND document->>'provider_resource_id'=member->>'instance_id' AND document->>'account_id'=r->'binding'->>'account_id' AND document->>'region'=r->'binding'->>'region') THEN RAISE EXCEPTION 'fleet history member inventory mapping differs'; END IF;
   IF member->'hardware' IS NOT NULL AND member->'hardware'<>'null'::jsonb THEN
    hardware:=fleet_history_native_reference(NEW.tenant_id,member->'hardware',r->'binding','AWS_EC2_HARDWARE',member->>'instance_id');
    IF member->'launch_time' IS NOT NULL AND member->'launch_time'<>'null'::jsonb AND ((hardware->'native'->'instance'->>'launch_time') IS NULL OR (member->>'launch_time')::timestamptz IS DISTINCT FROM (hardware->'native'->'instance'->>'launch_time')::timestamptz) THEN RAISE EXCEPTION 'fleet history launch incarnation unobserved'; END IF;
   ELSIF member->'launch_time' IS NOT NULL AND member->'launch_time'<>'null'::jsonb THEN RAISE EXCEPTION 'fleet history launch requires issued native evidence'; END IF;
  END LOOP;
  IF NEW.corrects_id IS DISTINCT FROM nullif(NEW.document->>'corrects_id','') THEN RAISE EXCEPTION 'fleet history correction column differs'; END IF;
  IF NEW.corrects_id IS NOT NULL THEN SELECT document INTO old FROM fleet_history_observations WHERE tenant_id=NEW.tenant_id AND id=NEW.corrects_id;IF old IS NULL OR old->>'registration_id' IS DISTINCT FROM NEW.registration_id OR (old->>'registration_version')::bigint IS DISTINCT FROM NEW.registration_version OR (old->>'observed_at')::timestamptz IS DISTINCT FROM NEW.observed_at THEN RAISE EXCEPTION 'fleet history correction logical point differs'; END IF;END IF;
 ELSIF TG_TABLE_NAME='fleet_history_scopes' THEN
  PERFORM fleet_history_lock(NEW.tenant_id,NEW.registration_id);
  SELECT document INTO r FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id AND version=NEW.registration_version;
  SELECT document INTO definition FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=NEW.definition_id AND version=NEW.definition_version AND registration_id=NEW.registration_id AND registration_version=NEW.registration_version;
  IF r IS NULL OR definition IS NULL OR NEW.registration_version IS DISTINCT FROM (SELECT max(version) FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.registration_id) OR NEW.definition_version IS DISTINCT FROM (SELECT max(version) FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=NEW.definition_id) OR NEW.document->>'status' IS DISTINCT FROM 'BLOCKED' OR NEW.document->>'membership_status' IS DISTINCT FROM 'INTERVAL_OWNERSHIP_UNPROVEN' OR NEW.document->>'input_hash' IS DISTINCT FROM NEW.input_hash OR NEW.document->>'analysis_hash' IS DISTINCT FROM NEW.analysis_hash OR NEW.document->>'reference_root' IS DISTINCT FROM NEW.reference_root OR (NEW.document->>'reference_count')::integer IS DISTINCT FROM NEW.reference_count OR NEW.document->'binding' IS DISTINCT FROM r->'binding' OR abs(extract(epoch FROM (clock_timestamp()-(NEW.document->>'as_of')::timestamptz)))>30 OR (NEW.document->>'end')::timestamptz IS DISTINCT FROM date_trunc('day',(NEW.document->>'as_of')::timestamptz AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR (NEW.document->>'end')::timestamptz-(NEW.document->>'start')::timestamptz<>interval '14 days' OR NEW.document ?| ARRAY['execution_authorized','verified_saving','currency','complete','attested'] THEN RAISE EXCEPTION 'fleet history blocked scope seal differs'; END IF;
 ELSIF TG_TABLE_NAME='fleet_history_scope_references' THEN
  SELECT * INTO scope FROM fleet_history_scopes WHERE tenant_id=NEW.tenant_id AND id=NEW.scope_id;
  IF scope.id IS NULL OR NEW.ordinal>scope.reference_count THEN RAISE EXCEPTION 'fleet history scope reference missing'; END IF;
  IF NEW.kind='REGISTRATION' AND (NEW.reference_id IS DISTINCT FROM scope.registration_id OR NEW.document->>'id' IS DISTINCT FROM scope.registration_id OR (NEW.document->>'version')::bigint IS DISTINCT FROM scope.registration_version OR NOT EXISTS(SELECT 1 FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=scope.registration_id AND version=scope.registration_version AND content_hash=NEW.document->>'hash')) THEN RAISE EXCEPTION 'fleet history registration reference differs'; END IF;
  IF NEW.kind='DEFINITION' AND (NEW.reference_id IS DISTINCT FROM scope.definition_id OR NEW.document->>'id' IS DISTINCT FROM scope.definition_id OR (NEW.document->>'version')::bigint IS DISTINCT FROM scope.definition_version OR NOT EXISTS(SELECT 1 FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=scope.definition_id AND version=scope.definition_version AND content_hash=NEW.document->>'hash')) THEN RAISE EXCEPTION 'fleet history demand definition reference differs'; END IF;
  IF NEW.kind='OBSERVATION' AND (NEW.document->>'id' IS DISTINCT FROM NEW.reference_id OR NOT EXISTS(SELECT 1 FROM fleet_history_observations WHERE tenant_id=NEW.tenant_id AND id=NEW.reference_id AND registration_id=scope.registration_id AND registration_version=scope.registration_version AND observed_at>=(scope.document->>'start')::timestamptz AND observed_at<=(scope.document->>'end')::timestamptz AND content_hash=NEW.document->>'hash')) THEN RAISE EXCEPTION 'fleet history observation reference differs'; END IF;
  IF NEW.kind='DEMAND_RECEIPT' AND NOT EXISTS(SELECT 1 FROM activity_receipts a JOIN fleet_demand_definitions d ON d.tenant_id=a.tenant_id AND d.source_id=a.source_id WHERE a.tenant_id=NEW.tenant_id AND a.id=NEW.reference_id AND d.id=scope.definition_id AND d.version=scope.definition_version AND a.body_sha256=NEW.document->>'body_sha256' AND fleet_history_json_hash(a.document)=NEW.document->>'canonical_hash' AND a.interval_start>=(scope.document->>'start')::timestamptz AND a.interval_end<=(scope.document->>'end')::timestamptz) THEN RAISE EXCEPTION 'fleet history original activity reference differs'; END IF;
  IF NEW.kind='SOURCE_STATE' THEN
   IF NOT NEW.document ?& ARRAY['source_id','source_system','config_hash','binding','status','checked_at'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['source_id','source_system','source_registration_version','config_hash','binding','status','checked_at'])) THEN RAISE EXCEPTION 'fleet history current source shape differs'; END IF;
   IF NEW.reference_id IS DISTINCT FROM (NEW.document->>'source_system')||':'||(NEW.document->>'source_id') OR NEW.document->'binding' IS DISTINCT FROM scope.document->'binding' OR (NEW.document->>'checked_at')::timestamptz IS DISTINCT FROM (scope.document->>'as_of')::timestamptz THEN RAISE EXCEPTION 'fleet history current source identity differs'; END IF;
   SELECT document INTO r FROM fleet_history_registrations WHERE tenant_id=NEW.tenant_id AND id=scope.registration_id AND version=scope.registration_version;
   SELECT document INTO definition FROM fleet_demand_definitions WHERE tenant_id=NEW.tenant_id AND id=scope.definition_id AND version=scope.definition_version;
   IF NEW.document->>'source_system'='ACTIVITY_SOURCE' THEN
    SELECT document INTO source FROM activity_sources WHERE tenant_id=NEW.tenant_id AND id=NEW.document->>'source_id';
    expected_status:=CASE WHEN source->>'enabled' IS DISTINCT FROM 'true' THEN 'REVOKED' WHEN fleet_history_json_hash(source) IS DISTINCT FROM definition->>'source_config_hash' THEN 'SUPERSEDED' ELSE 'ACTIVE' END;
    IF source IS NULL OR NEW.document->>'source_id' IS DISTINCT FROM definition->>'source_id' OR NEW.document ? 'source_registration_version' OR NEW.document->>'config_hash' IS DISTINCT FROM fleet_history_json_hash(source) OR NEW.document->>'status' IS DISTINCT FROM expected_status THEN RAISE EXCEPTION 'fleet history activity lifecycle differs'; END IF;
   ELSIF NEW.document->>'source_system'='AWS_SOURCE_CONNECTION' THEN
    IF NOT fleet_history_source_lock(NEW.tenant_id,NEW.document->>'source_id') THEN RAISE EXCEPTION 'fleet history current native source missing'; END IF;
    SELECT document,version INTO source,source_version FROM source_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.document->>'source_id';
    IF NEW.document->>'source_id'=r->>'source_id' THEN expected_hash:=r->>'source_config_hash';
    ELSE SELECT m->'hardware'->>'config_hash' INTO expected_hash FROM fleet_history_observations o CROSS JOIN LATERAL jsonb_array_elements(o.document->'members') m WHERE o.tenant_id=NEW.tenant_id AND o.registration_id=scope.registration_id AND o.registration_version=scope.registration_version AND o.observed_at>=(scope.document->>'start')::timestamptz AND o.observed_at<=(scope.document->>'end')::timestamptz AND m->'hardware'->>'source_id'=NEW.document->>'source_id' ORDER BY o.observed_at,o.id LIMIT 1; END IF;
    SELECT document INTO source_status FROM source_checkpoints WHERE tenant_id=NEW.tenant_id AND source_id=NEW.document->>'source_id' AND checkpoint_key='status';
    expected_status:=CASE WHEN source->>'enabled' IS DISTINCT FROM 'true' OR coalesce((source->>'revoked')::boolean,false) THEN 'REVOKED' WHEN fleet_history_source_config(source) IS DISTINCT FROM expected_hash THEN 'SUPERSEDED' WHEN source_status->>'status' IS DISTINCT FROM 'HEALTHY' OR source_status->>'last_sync_at' IS NULL OR (source_status->>'last_sync_at')::timestamptz>(scope.document->>'as_of')::timestamptz+interval '5 seconds' OR (scope.document->>'as_of')::timestamptz-(source_status->>'last_sync_at')::timestamptz>interval '5 minutes' THEN 'DEGRADED' ELSE 'ACTIVE' END;
    IF expected_hash IS NULL OR NEW.document->>'config_hash' IS DISTINCT FROM fleet_history_source_config(source) OR (NEW.document->>'source_registration_version')::bigint IS DISTINCT FROM source_version OR NEW.document->>'status' IS DISTINCT FROM expected_status THEN RAISE EXCEPTION 'fleet history native lifecycle differs'; END IF;
   ELSE RAISE EXCEPTION 'fleet history source namespace unsupported'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fleet_history_registrations','fleet_demand_definitions','fleet_history_observations','fleet_history_scopes','fleet_history_scope_references'] LOOP
 EXECUTE format('CREATE TRIGGER %I BEFORE INSERT ON %I FOR EACH ROW EXECUTE FUNCTION guard_fleet_history()',tab||'_writer',tab);
 END LOOP;END $$;
CREATE FUNCTION seal_fleet_history_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE n integer;root text;BEGIN
 SELECT count(*),encode(sha256(convert_to(coalesce(string_agg(ordinal::text||':'||content_hash,',' ORDER BY ordinal),''),'UTF8')),'hex') INTO n,root FROM fleet_history_scope_references WHERE tenant_id=NEW.tenant_id AND scope_id=NEW.id;
 IF n<>NEW.reference_count OR root IS DISTINCT FROM NEW.reference_root OR (SELECT min(ordinal) FROM fleet_history_scope_references WHERE tenant_id=NEW.tenant_id AND scope_id=NEW.id)<>1 OR (SELECT max(ordinal) FROM fleet_history_scope_references WHERE tenant_id=NEW.tenant_id AND scope_id=NEW.id)<>n THEN RAISE EXCEPTION 'fleet history immutable reference root incomplete'; END IF;RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER fleet_history_scope_seal AFTER INSERT ON fleet_history_scopes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION seal_fleet_history_scope();
REVOKE ALL ON FUNCTION fleet_history_json_text(jsonb),fleet_history_json_hash(jsonb),fleet_history_source_config(jsonb),fleet_history_lock(text,text),fleet_history_native_reference(text,jsonb,jsonb,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_history_json_text(jsonb),fleet_history_json_hash(jsonb),fleet_history_source_config(jsonb),fleet_history_lock(text,text),fleet_history_native_reference(text,jsonb,jsonb,text,text) TO finops_api,finops_ingester;
